import {state,update} from './store.js';
import {attachCanvasGestures} from './map-gestures.js';
import {roomTypes,saveRoom,nextRoomPosition,nextSeatPosition,locationForPerson,assignPerson,validateIp,resizeFloor,moveSeat} from './office-model.js';

let ui,activeView,map,resizeObserver,peopleQuery='',peopleDepartment='';
const $=(s,root=document)=>root.querySelector(s);
const secretTimers=new Map();
const person=id=>state.people.find(p=>p.id===id);
const floorData=()=>state.office.floors.find(f=>f.id===map.floorId);
const e=s=>ui.esc(s);
const i=name=>ui.icon(name);
const btn=(action,label,attrs='',cls='btn')=>`<button type="button" class="${cls}" data-office="${action}" ${attrs}>${label}</button>`;
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('');
const field=(id,label,value='',type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${e(value)}" ${extra}></div>`;
const formActions=(label='Сохранить')=>`<div id="office-form-error" role="alert"></div><div class="modal-footer">${btn('cancel','Отмена')}<button class="btn btn-primary" type="submit">${i('check')}${label}</button></div>`;
function formError(error){const target=$('#office-form-error');if(target){target.textContent=error.message||'Не удалось сохранить изменения.';target.className='form-error';}else ui.toast(error.message);}
function bindForm(id,handler){$(id).addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{await handler();}catch(error){formError(error);}finally{if(button.isConnected)button.disabled=false;}});}

export function hideOfficeSecrets(){for(const timer of secretTimers.values())clearTimeout(timer);secretTimers.clear();document.querySelectorAll('[data-secret-id]').forEach(el=>{el.textContent='••••••••';el.classList.remove('revealed');});document.querySelectorAll('[data-office="secret"]').forEach(el=>{el.setAttribute('aria-pressed','false');el.setAttribute('aria-label',`Показать пароль ${person(el.dataset.person)?.name||''}`);el.innerHTML=`${i('eye')}Показать`;});}
function toggleSecret(id){const revealed=secretTimers.has(id);hideOfficeSecrets();if(revealed)return;document.querySelectorAll('[data-secret-id]').forEach(el=>{if(el.dataset.secretId===id){el.textContent=state.demoCredentials[id]||'Не задан';el.classList.add('revealed');}});document.querySelectorAll('[data-office="secret"]').forEach(el=>{if(el.dataset.person===id){el.setAttribute('aria-pressed','true');el.setAttribute('aria-label',`Скрыть пароль ${person(id)?.name||''}`);el.innerHTML=`${i('lock')}Скрыть`;}});secretTimers.set(id,setTimeout(hideOfficeSecrets,20000));}
function secretRow(p){return `<div class="person-secret"><div><span class="secret-label">Пароль · демо</span><span class="secret-value" data-secret-id="${e(p.id)}" aria-live="polite">••••••••</span></div>${btn('secret',`${i('eye')}Показать`,`data-person="${e(p.id)}" aria-label="Показать пароль ${e(p.name)}" aria-pressed="false"`,'btn btn-small')}</div>`;}
function employeeCard(p){const loc=locationForPerson(state.office,p.id);return `<article class="person-card" data-employee-id="${e(p.id)}" tabindex="0" aria-label="Сотрудник ${e(p.name)}"><div class="between"><span class="avatar ${e(p.color)}">${e(p.initials)}</span><div class="person-card-tools">${btn('edit-person',i('edit'),`data-person="${e(p.id)}" aria-label="Редактировать сотрудника ${e(p.name)}"`,'icon-btn')}${btn('person-menu',i('more'),`data-person="${e(p.id)}" aria-label="Действия с сотрудником ${e(p.name)}" aria-haspopup="menu" aria-expanded="false"`,'icon-btn')}</div></div><h3>${e(p.name)}</h3><p class="job">${e(p.job)}</p><div class="person-details"><div>${i('building')}<span>${e(p.department)}</span></div><div>${i('pin')}<span>${loc?`Этаж ${e(loc.floor.number)} · место ${e(loc.seat.number)}`:'Рабочее место не назначено'}</span></div><div>${i('phone')}<span>Внутренний: ${e(p.phone||'—')}</span></div><div>${i('mail')}<a href="mailto:${e(p.email)}">${e(p.email||'Не указан')}</a></div><div>${i('phone')}<span>Личный: ${e(p.personalPhone||'Не указан')}</span></div></div>${secretRow(p)}${employeeNote(p)}${loc?`<a href="#/map?person=${e(p.id)}" class="text-link">Показать на карте ${i('arrow')}</a>`:'<span class="tiny muted" style="display:block;margin-top:18px">Назначьте место в редакторе карты</span>'}</article>`;}
export function mountPeople(options){ui=options;activeView='people';resizeObserver?.disconnect();hideOfficeSecrets();$('#main-content').innerHTML=`${ui.titleRow('Люди рядом.','Контакты, учётные данные и рабочие места.',false)}<div class="notice">${i('info')}Демонстрационные данные. Изменения сохраняются в этом браузере; реальные доступы подключаются через корпоративное хранилище.</div><div class="toolbar"><label class="search-field">${i('search')}<input id="people-search" type="search" placeholder="Имя, email, отдел или место" aria-label="Поиск сотрудника" value="${e(peopleQuery)}"></label><select id="people-department" class="field-select" aria-label="Отдел"><option value="">Все отделы</option>${[...new Set(state.people.map(p=>p.department))].map(d=>`<option ${d===peopleDepartment?'selected':''}>${e(d)}</option>`).join('')}</select></div><div id="people-results" class="people-grid"></div>${ui.footer()}`;refreshPeople();$('#people-search').addEventListener('input',event=>{peopleQuery=event.target.value;refreshPeople();});$('#people-department').addEventListener('change',event=>{peopleDepartment=event.target.value;refreshPeople();});}
function refreshPeople(){hideOfficeSecrets();const terms=peopleQuery.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean);const items=state.people.filter(p=>{const loc=locationForPerson(state.office,p.id);const haystack=[p.name,p.email,p.personalPhone,p.phone,p.department,p.notes,loc?.seat.number,loc?.seat.pc,loc?.room.name].join(' ').toLocaleLowerCase('ru');return(!peopleDepartment||p.department===peopleDepartment)&&terms.every(t=>haystack.includes(t));});$('#people-results').innerHTML=items.length?items.map(employeeCard).join(''):'<div class="empty"><h2>Сотрудник не найден</h2><p>Проверьте имя или выберите другой отдел.</p></div>';}
function editPerson(id){const p=person(id);if(!p)return;hideOfficeSecrets();ui.showModal('Карточка сотрудника',`<form id="person-edit-form"><div class="office-form-grid">${field('person-name','Имя и фамилия',p.name,'text','required maxlength="100"')}${field('person-job','Должность',p.job,'text','maxlength="120"')}${field('person-department','Отдел',p.department,'text','required maxlength="100"')}${field('person-extension','Внутренний телефон',p.phone,'text','maxlength="30"')}${field('person-email','Email',p.email,'email','maxlength="200"')}${field('person-mobile','Личный телефон',p.personalPhone,'tel','maxlength="40"')}${notesField(p)}</div>${field('person-password','Новый пароль · демо','','password','autocomplete="new-password" maxlength="200" placeholder="Оставьте пустым, чтобы не менять"')}<p class="field-help">Поле предназначено для проверки интерфейса. Реальные пароли — через корпоративное хранилище. Демо-пароли не попадают в JSON-экспорт.</p>${formActions()}</form>`,true);bindForm('#person-edit-form',async()=>{const name=$('#person-name').value.trim(),department=$('#person-department').value.trim();if(!name||!department)throw new Error('Укажите имя и отдел.');const values={name,department,job:$('#person-job').value.trim(),phone:$('#person-extension').value.trim(),email:$('#person-email').value.trim(),personalPhone:$('#person-mobile').value.trim(),initials:initials(name),notes:$('#person-notes').value.trim()};const password=$('#person-password').value;await update(s=>{const entry=s.people.find(x=>x.id===id);if((entry.notes||'')!==values.notes)entry.notesUpdatedAt=new Date().toISOString();Object.assign(entry,values);if(password)s.demoCredentials[id]=password;});ui.closeModal();activeView==='people'?mountPeople(ui):redrawMap();ui.toast('Карточка сотрудника сохранена');});}

export function disposeOffice(){closePersonMenu();hideOfficeSecrets();resizeObserver?.disconnect();resizeObserver=null;if(map?.gestures)map.gestures.clear();activeView=null;}
export function mountMap(options){ui=options;activeView='map';hideOfficeSecrets();resizeObserver?.disconnect();const requested=options.params?.get('person');const loc=requested?locationForPerson(state.office,requested):null;const initialFloor=loc?.floor||state.office.floors.find(f=>f.id===map?.floorId)||state.office.floors[0];map={floorId:initialFloor.id,seatId:loc?.seat.id||initialFloor.seats[0]?.id||'',roomId:loc?.room.id||(matchMedia('(max-width:760px)').matches?initialFloor.rooms[0]?.id||'':''),editing:false,mode:'plan',camera:null,gestures:new Map(),moved:false};renderMapPage();}
function renderMapPage(){resizeObserver?.disconnect();const f=floorData();$('#main-content').innerHTML=`${ui.titleRow('Офис как на ладони.','Кабинеты, сотрудники и оборудование на одном плане.',false)}<div class="office-page-tools"><div class="office-context"><span class="category-icon green">${i('building')}</span><div><strong>БЦ «Горизонт»</strong><span>Локальная демонстрация · изменения сохраняются</span></div></div>${btn('toggle-edit',`${i(map.editing?'check':'edit')}${map.editing?'Готово':'Редактировать карту'}`,'',map.editing?'btn btn-primary':'btn')}</div><div class="office-edit-tools ${map.editing?'':'hidden'}">${btn('add-room',`${i('plus')}Добавить кабинет`)}${btn('add-seat',`${i('monitor')}Добавить место`)}${btn('resize-floor',`${i('map')}Размер плана`)}${btn('add-floor',`${i('plus')}Добавить этаж`)}<p>Перетаскивайте места · Shift — по одной оси · Пробел — двигать карту</p></div><div class="office-layout"><section class="office-plan-panel"><div class="office-map-top"><select id="office-floor" class="field-select" aria-label="Выбрать этаж">${state.office.floors.map(f=>`<option value="${f.id}" ${f.id===map.floorId?'selected':''}>${e(f.name)}</option>`).join('')}</select><div class="office-mode" role="group" aria-label="Отображение карты">${btn('mode-plan',`${i('map')}Схема`,'aria-pressed="'+(map.mode==='plan')+'"',map.mode==='plan'?'active':'')}${btn('mode-list',`${i('list')}Список`,'aria-pressed="'+(map.mode==='list')+'"',map.mode==='list'?'active':'')}</div></div><div class="office-search-row"><label class="search-field">${i('search')}<input id="office-search" type="search" placeholder="Сотрудник, кабинет, место или IP" aria-label="Найти на карте"></label><select id="office-room" class="field-select" aria-label="Выбрать кабинет"><option value="">Все кабинеты</option>${f.rooms.map(r=>`<option value="${r.id}" ${r.id===map.roomId?'selected':''}>${e(r.name)}</option>`).join('')}</select></div><div id="office-search-results" class="office-search-results hidden"></div><div id="office-viewport" class="office-viewport ${map.editing?'editing':''} ${map.mode==='list'?'hidden':''}" aria-label="Интерактивная карта. Перемещайте пальцем, увеличивайте двумя пальцами или кнопками"><svg id="office-svg" class="office-svg" role="group" aria-label="План ${e(f.name)}"></svg><div class="office-zoom-controls">${btn('zoom-out','−','aria-label="Уменьшить карту"','icon-btn')}<output id="office-zoom" aria-label="Масштаб">100%</output>${btn('zoom-in','+','aria-label="Увеличить карту"','icon-btn')}<span></span>${btn('fit',i('map'),'aria-label="Показать весь план"','icon-btn')}</div></div><div id="office-seat-list" class="office-seat-list ${map.mode==='list'?'':'hidden'}"></div><div class="office-map-bottom"><span><i class="map-marker"></i>Занято</span><span><i class="map-marker free"></i>Свободно</span><span class="office-map-help" id="office-drag-status" role="status">${map.editing?'Перетащите место · стрелки — точная подстройка':'Перемещайте схему · увеличивайте двумя пальцами'}</span></div></section><aside id="office-detail" class="panel office-detail"></aside></div>${ui.footer()}`;drawFloor();renderSeatList();renderDetails();bindMapGestures();$('#office-floor').addEventListener('change',event=>{map.floorId=event.target.value;map.roomId='';map.seatId=floorData().seats[0]?.id||'';map.camera=null;renderMapPage();});$('#office-room').addEventListener('change',event=>{map.roomId=event.target.value;map.camera=null;drawFloor();renderSeatList();if(map.roomId){map.seatId='';renderDetails();}});$('#office-search').addEventListener('input',event=>searchMap(event.target.value));resizeObserver=new ResizeObserver(()=>{if($('#office-svg'))applyCamera();});resizeObserver.observe($('#office-viewport'));}
function personForSeat(s){return person(s.personId);}
function defaultCamera(){const f=floorData(),r=f.rooms.find(r=>r.id===map.roomId);return r?{x:r.x-30,y:r.y-30,w:r.width+60,h:r.height+60}:{x:0,y:0,w:f.width,h:f.height};}
function applyCamera(){const svg=$('#office-svg');if(!svg)return;map.camera||=defaultCamera();const c=map.camera;svg.setAttribute('viewBox',`${c.x} ${c.y} ${c.w} ${c.h}`);const percent=Math.round(defaultCamera().w/c.w*100);$('#office-zoom').textContent=`${percent}%`;}
function drawFloor(){const f=floorData();const svg=$('#office-svg');svg.innerHTML=`<defs><pattern id="office-dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#dce5d2"/></pattern></defs><rect x="0" y="0" width="${f.width}" height="${f.height}" fill="url(#office-dots)"/><rect x="16" y="16" width="${f.width-32}" height="${f.height-32}" rx="10" fill="none" stroke="#d7e1cb" stroke-width="2" stroke-dasharray="5 6"/>${f.rooms.map(r=>`<g class="office-room ${map.roomId===r.id?'selected':''}" data-room-shape="${r.id}" transform="translate(${r.x} ${r.y})"><rect class="office-room-bg" width="${r.width}" height="${r.height}" rx="9"/><rect class="office-room-title-bg" width="${r.width}" height="57" rx="9"/><g data-room-drag="${r.id}" data-office="select-room" data-room="${r.id}" role="button" tabindex="0" aria-label="Кабинет ${e(r.name)}"><rect width="${r.width}" height="57" fill="transparent"/><text x="20" y="27" class="office-room-name">${e(r.name.length>Math.floor((r.width-40)/12)?r.name.slice(0,Math.floor((r.width-40)/12)-1)+'…':r.name)}</text><text x="20" y="45" class="office-room-type">${roomTypes[r.type]||'Кабинет'} · ${f.seats.filter(s=>s.roomId===r.id).length} мест</text></g>${r.type==='meeting'&&!f.seats.some(s=>s.roomId===r.id)?`<rect x="${r.width/2-65}" y="${r.height/2-15}" width="130" height="65" rx="24" fill="#e9efdf" stroke="#cbd9ba"/><path d="M${r.width/2-40} ${r.height/2-25}h80M${r.width/2-40} ${r.height/2+60}h80" stroke="#d1dec0" stroke-width="9" stroke-dasharray="14 14" stroke-linecap="round"/>`:''}${r.type==='printing'&&!f.seats.some(s=>s.roomId===r.id)?`<g transform="translate(${r.width/2-22} ${r.height/2-10})"><rect width="44" height="36" rx="5" fill="#dfe9d2" stroke="#adbf98"/><path d="M8 0v-13h28V0M8 24h28v24H8M30 10h5" fill="#f8faf5" stroke="#9db484" stroke-width="2"/></g>`:''}${f.seats.filter(s=>s.roomId===r.id).map(s=>seatSvg(s)).join('')}</g>`).join('')}`;applyCamera();}
function seatSvg(s){const p=personForSeat(s);const name=p?p.name.split(' ').map((w,i)=>i===0?w:w[0]+'.').join(' '):'Свободно';return `<g class="office-seat ${p?'occupied':'free'} ${map.seatId===s.id?'selected':''}" data-office="select-seat" data-seat="${s.id}" data-employee-id="${e(p?.id||'')}" role="button" tabindex="0" aria-label="${e(p?.name||'Свободно')}, место ${e(s.number)}" transform="translate(${s.x} ${s.y})"><rect class="seat-hit" x="-9" y="-29" width="130" height="110" rx="10" fill="transparent"/><rect class="office-desk-body" width="110" height="57" rx="6"/><rect x="38" y="8" width="34" height="21" rx="2" class="office-monitor"/><path d="M55 29v5m-8 0h16" stroke="#9eb18a"/><rect x="37" y="39" width="37" height="6" rx="2" fill="#cddcbd"/><path d="M38 70q17 11 35 0" stroke="#d4dfc8" stroke-width="9" stroke-linecap="round"/><text x="0" y="-10" class="office-seat-person">${e(name.length>12?name.slice(0,11)+'…':name)}</text><text x="8" y="53" class="office-seat-number">${e(s.number)}</text><text class="seat-coordinate" x="0" y="102">X ${s.x} · Y ${s.y}</text><circle cx="98" cy="46" r="4" fill="${p?'#82a85e':'#ccd6c1'}"/></g>`;}
function renderSeatList(){const f=floorData();const rooms=map.roomId?f.rooms.filter(r=>r.id===map.roomId):f.rooms;$('#office-seat-list').innerHTML=rooms.map(r=>`<section><h3>${e(r.name)}</h3>${f.seats.filter(s=>s.roomId===r.id).map(s=>{const p=personForSeat(s);return btn('select-seat',`<span class="seat-list-icon ${p?'':'free'}">${i('monitor')}</span><span><strong>Место ${e(s.number)}</strong><small>${e(p?.name||'Свободное место')}</small></span>${i('chevron')}`,`data-seat="${s.id}"`,'office-seat-row');}).join('')||'<p class="office-empty-room">Рабочих мест пока нет</p>'}</section>`).join('');}
function seatDetails(s){const p=personForSeat(s),f=floorData(),r=f.rooms.find(r=>r.id===s.roomId);return `<div class="between"><span class="badge neutral">Место ${e(s.number)}</span><span class="badge ${p?'':'neutral'}">${p?'Занято':'Свободно'}</span></div>${p?`<span class="avatar ${e(p.color)}">${e(p.initials)}</span><h2>${e(p.name)}</h2><p>${e(p.job)}</p>`:`<span class="avatar green">${i('monitor')}</span><h2>Свободное место</h2><p>Назначьте сотрудника через редактирование</p>`}<dl class="equipment-list"><div><dt>Кабинет</dt><dd>${e(r?.name||'—')}</dd></div><div><dt>Этаж</dt><dd>${e(f.name)}</dd></div>${p?`<div><dt>Отдел</dt><dd>${e(p.department)}</dd></div>`:''}<div><dt>Компьютер</dt><dd>${e(s.pc||'Не указан')}</dd></div><div><dt>Телефон</dt><dd>${e(s.phone||p?.phone||'Не указан')}</dd></div><div><dt>IP телефона</dt><dd class="mono">${e(s.phoneIp||'Не указан')}</dd></div><div class="equipment-divider"><dt>Принтер</dt><dd>${e(s.printerName||'Не указан')}</dd></div><div><dt>IP принтера</dt><dd class="mono">${e(s.printerIp||'Не указан')}</dd></div><div><dt>Модель принтера</dt><dd>${e(s.printerModel||'Не указана')}</dd></div>${map.editing?`<div><dt>Положение</dt><dd>X ${s.x} · Y ${s.y}</dd></div>`:''}</dl>${p?employeeNote(p):''}${btn('edit-seat',`${i('edit')}Редактировать место`,`data-seat="${s.id}"`,'btn btn-primary office-detail-action')}${p?btn('edit-person',`${i('users')}Карточка сотрудника`,`data-person="${p.id}"`,'btn office-detail-action'):''}`;}
function renderDetails(){const f=floorData(),s=f.seats.find(s=>s.id===map.seatId),r=f.rooms.find(r=>r.id===map.roomId);$('#office-detail').innerHTML=s?seatDetails(s):r?`<span class="badge neutral">${roomTypes[r.type]}</span><h2 style="margin-top:20px">${e(r.name)}</h2><p>${e(f.name)}</p><dl class="equipment-list"><div><dt>Размер</dt><dd>${r.width} × ${r.height}</dd></div><div><dt>Мест</dt><dd>${f.seats.filter(s=>s.roomId===r.id).length}</dd></div></dl>${btn('edit-room',`${i('edit')}Изменить кабинет`,`data-room="${r.id}"`,'btn btn-primary office-detail-action')}${btn('add-seat',`${i('plus')}Добавить место`,`data-room="${r.id}"`,'btn office-detail-action')}`:`<span class="category-icon green">${i('map')}</span><h2 style="margin-top:20px">Выберите место</h2><p>Нажмите на рабочий стол на схеме или откройте список.</p>${btn('add-room',`${i('plus')}Добавить кабинет`,'','btn office-detail-action')}`;}
function selectSeat(id){map.seatId=id;const s=floorData().seats.find(s=>s.id===id);if(!s)return;drawFloor();renderDetails();if(matchMedia('(max-width:760px)').matches){ui.showModal(`Место ${e(s.number)}`,seatDetails(s));$('.modal').classList.add('office-detail-sheet');$('.overlay').classList.add('office-sheet-overlay');}}
function searchMap(query){
 const f=floorData(),terms=query.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean),target=$('#office-search-results');
 if(!terms.length){target.classList.add('hidden');return;}
 const rooms=f.rooms.filter(r=>terms.every(t=>r.name.toLocaleLowerCase('ru').includes(t))).slice(0,3);
 const matches=f.seats.filter(s=>{const p=personForSeat(s),r=f.rooms.find(r=>r.id===s.roomId);const text=[s.number,s.phoneIp,s.printerName,s.printerIp,s.printerModel,s.pc,p?.name,r?.name].join(' ').toLocaleLowerCase('ru');return terms.every(t=>text.includes(t));}).slice(0,8);
 target.classList.remove('hidden');
 target.innerHTML=rooms.map(r=>btn('find-room',`<span>${i('building')} <strong>${e(r.name)}</strong></span>${i('arrow')}`,`data-room="${r.id}"`,'office-search-result')).join('')+matches.map(s=>btn('find-seat',`<span><strong>${e(s.number)}</strong> · ${e(personForSeat(s)?.name||'Свободно')}</span>${i('arrow')}`,`data-seat="${s.id}"`,'office-search-result')).join('')||'<p>На этом этаже ничего не найдено</p>';
}

function zoom(factor,anchor){const c=map.camera,limit=defaultCamera();const next=Math.max(limit.w*.15,Math.min(limit.w*2,c.w*factor));factor=next/c.w;const focus=anchor||{x:c.x+c.w/2,y:c.y+c.h/2};map.camera={x:focus.x-(focus.x-c.x)*factor,y:focus.y-(focus.y-c.y)*factor,w:c.w*factor,h:c.h*factor};applyCamera();}
function worldPoint(clientX,clientY){const box=$('#office-svg').getBoundingClientRect(),c=map.camera;const scale=Math.max(c.w/box.width,c.h/box.height);return{x:c.x+c.w/2+(clientX-box.left-box.width/2)*scale,y:c.y+c.h/2+(clientY-box.top-box.height/2)*scale,scale};}
function mapStatus(message,error=false){const el=$('#office-drag-status');if(el){el.textContent=message;el.classList.toggle('error',error);}}
function bindMapGestures(){const session=map;attachCanvasGestures({svg:$('#office-svg'),map:session,getFloor:floorData,toWorld:worldPoint,zoom,applyCamera,isActive:()=>activeView==='map'&&map===session,render:()=>{drawFloor();renderDetails();},report:mapStatus,saveSeat:(id,point)=>update(s=>moveSeat(s.office.floors.find(f=>f.id===session.floorId),id,point.x,point.y,{snap:1})),saveRoom:room=>update(s=>saveRoom(s.office.floors.find(f=>f.id===session.floorId),room))});}


function nextSeatNumber(floor){let n=1;while(floor.seats.some(s=>s.number===`${floor.number}.${String(n).padStart(2,'0')}`))n++;return`${floor.number}.${String(n).padStart(2,'0')}`;}
function redrawMap(){if(activeView==='map')renderMapPage();}
function showRoomForm(id){const f=floorData(),existing=f.rooms.find(r=>r.id===id),position=nextRoomPosition(f);const room=existing||{id:crypto.randomUUID(),name:'',type:'office',...position,width:480,height:440};ui.showModal(existing?'Изменить кабинет':'Добавить кабинет',`<form id="room-form"><div class="office-form-grid">${field('room-name','Название кабинета',room.name,'text','required maxlength="80" placeholder="Например: 305 · Бухгалтерия"')}<div class="field"><label for="room-type">Тип помещения</label><select id="room-type">${Object.entries(roomTypes).map(([id,label])=>`<option value="${id}" ${id===room.type?'selected':''}>${label}</option>`).join('')}</select></div>${!existing?`<div class="field"><label for="room-position">Расположение</label><select id="room-position"><option value="right">Справа от существующих</option><option value="bottom">Снизу от существующих</option><option value="custom">Указать координаты</option></select></div>${field('room-seat-count','Рабочих мест',4,'number','min="0" max="24" required')}`:''}${field('room-x','Положение X',room.x,'number','min="20" max="5700" step="10" required')}${field('room-y','Положение Y',room.y,'number','min="20" max="5700" step="10" required')}${field('room-width','Ширина кабинета',room.width,'number','min="240" max="3000" step="10" required')}${field('room-height','Высота кабинета',room.height,'number','min="200" max="3000" step="10" required')}</div><p class="field-help">Размеры — условные единицы схемы. Если кабинет выходит за границу, план расширится автоматически. Кабинеты не должны пересекаться.</p>${formActions(existing?'Сохранить кабинет':'Добавить кабинет')}</form>`,true);$('#room-position')?.addEventListener('change',event=>{if(event.target.value==='custom')return;const point=nextRoomPosition(f,event.target.value);$('#room-x').value=point.x;$('#room-y').value=point.y;});for(const id of ['room-x','room-y'])$('#'+id).addEventListener('input',()=>{if($('#room-position'))$('#room-position').value='custom';});bindForm('#room-form',async()=>{const next={...room,name:$('#room-name').value.trim(),type:$('#room-type').value,x:Number($('#room-x').value),y:Number($('#room-y').value),width:Number($('#room-width').value),height:Number($('#room-height').value)};const count=existing?0:Number($('#room-seat-count').value);if(!Number.isInteger(count)||count<0||count>24)throw new Error('Количество мест должно быть от 0 до 24.');await update(s=>{const floor=s.office.floors.find(x=>x.id===map.floorId);saveRoom(floor,next);for(let n=0;n<count;n++){const point=nextSeatPosition(floor,next);floor.seats.push({id:crypto.randomUUID(),roomId:next.id,number:nextSeatNumber(floor),personId:'',pc:'',phone:'',phoneIp:'',printerName:'',printerIp:'',printerModel:'',...point});}});map.roomId=next.id;map.seatId='';map.camera=null;ui.closeModal();redrawMap();ui.toast(existing?'Кабинет обновлён':'Кабинет добавлен. План расширен при необходимости.');});}
function showSeatForm(id,roomId){const f=floorData(),existing=f.seats.find(s=>s.id===id);if(!f.rooms.length){ui.toast('Сначала добавьте кабинет');showRoomForm();return;}const seat=existing||{id:crypto.randomUUID(),roomId:roomId||map.roomId||f.rooms[0].id,number:nextSeatNumber(f),personId:'',pc:'',phone:'',phoneIp:'',printerName:'',printerIp:'',printerModel:''};ui.showModal(existing?'Оборудование рабочего места':'Добавить рабочее место',`<form id="seat-form"><div class="office-form-grid">${field('seat-number','Номер места',seat.number,'text','required maxlength="30"')}<div class="field"><label for="seat-room">Кабинет</label><select id="seat-room">${f.rooms.map(r=>`<option value="${r.id}" ${r.id===seat.roomId?'selected':''}>${e(r.name)}</option>`).join('')}</select></div><div class="field office-field-full"><label for="seat-person">Сотрудник</label><select id="seat-person"><option value="">Свободное место</option>${state.people.map(p=>`<option value="${p.id}" ${p.id===seat.personId?'selected':''}>${e(p.name)} · ${e(p.department)}</option>`).join('')}</select></div>${field('seat-pc','Компьютер',seat.pc,'text','maxlength="100" placeholder="Имя или инвентарный номер"')}${field('seat-phone','Внутренний телефон',seat.phone,'text','maxlength="30"')}${field('seat-phone-ip','IP телефона',seat.phoneIp,'text','inputmode="decimal" maxlength="15" placeholder="192.0.2.31"')}<div></div></div><h3 class="office-form-heading">Принтер</h3><div class="office-form-grid">${field('seat-printer-name','Имя принтера',seat.printerName,'text','maxlength="100"')}${field('seat-printer-ip','IP принтера',seat.printerIp,'text','inputmode="decimal" maxlength="15" placeholder="198.51.100.31"')}${field('seat-printer-model','Модель принтера',seat.printerModel,'text','maxlength="120"')}</div><p class="field-help">При назначении сотрудник переместится с предыдущего места. Пустые поля оборудования можно заполнить позже.</p>${formActions()}</form>`,true);$('#seat-person').addEventListener('change',event=>{const p=person(event.target.value);if(p&&!$('#seat-phone').value)$('#seat-phone').value=p.phone||'';});bindForm('#seat-form',async()=>{const values={...seat,number:$('#seat-number').value.trim(),roomId:$('#seat-room').value,personId:$('#seat-person').value,pc:$('#seat-pc').value.trim(),phone:$('#seat-phone').value.trim(),phoneIp:$('#seat-phone-ip').value.trim(),printerName:$('#seat-printer-name').value.trim(),printerIp:$('#seat-printer-ip').value.trim(),printerModel:$('#seat-printer-model').value.trim()};if(!values.number)throw new Error('Укажите номер рабочего места.');if(!validateIp(values.phoneIp)||!validateIp(values.printerIp))throw new Error('Проверьте IP-адрес: четыре числа от 0 до 255 через точку.');await update(s=>{const floor=s.office.floors.find(f=>f.id===map.floorId);if(floor.seats.some(x=>x.id!==seat.id&&x.number.toLocaleLowerCase()===values.number.toLocaleLowerCase()))throw new Error('На этаже уже есть место с таким номером.');if(!existing||values.roomId!==existing.roomId)Object.assign(values,nextSeatPosition(floor,floor.rooms.find(r=>r.id===values.roomId)));const index=floor.seats.findIndex(x=>x.id===seat.id);if(index<0)floor.seats.push(values);else floor.seats[index]=values;assignPerson(s.office,values.id,values.personId);});map.seatId=values.id;map.roomId='';ui.closeModal();redrawMap();ui.toast('Рабочее место сохранено');});}
function showFloorSize(){const f=floorData();ui.showModal('Размер плана этажа',`<form id="floor-size-form"><p class="field-help">Расширьте план справа и снизу, чтобы разместить новые кабинеты.</p><div class="office-form-grid">${field('floor-width','Ширина плана',f.width,'number','min="400" max="6000" step="10" required')}${field('floor-height','Высота плана',f.height,'number','min="350" max="6000" step="10" required')}</div>${formActions('Изменить размер')}</form>`);bindForm('#floor-size-form',async()=>{const width=Number($('#floor-width').value),height=Number($('#floor-height').value);await update(s=>resizeFloor(s.office.floors.find(f=>f.id===map.floorId),width,height));map.camera=null;ui.closeModal();redrawMap();ui.toast('Размер плана сохранён');});}
function showAddFloor(){const next=Math.max(...state.office.floors.map(f=>f.number))+1;ui.showModal('Добавить этаж',`<form id="add-floor-form">${field('floor-number','Номер этажа',next,'number','min="1" max="200" required')}${field('floor-name','Название',`${next}-й этаж`,'text','required maxlength="80"')}${formActions('Добавить этаж')}</form>`);bindForm('#add-floor-form',async()=>{const number=Number($('#floor-number').value),name=$('#floor-name').value.trim(),id=crypto.randomUUID();if(!name||!Number.isInteger(number)||number<1||number>200)throw new Error('Укажите название и целый номер этажа от 1 до 200.');await update(s=>{if(s.office.floors.some(f=>f.number===number))throw new Error('Такой этаж уже существует.');s.office.floors.push({id,number,name,width:1000,height:680,rooms:[],seats:[]});s.office.floors.sort((a,b)=>a.number-b.number);});map.floorId=id;map.roomId='';map.seatId='';map.camera=null;ui.closeModal();redrawMap();ui.toast('Этаж добавлен. Теперь добавьте кабинеты.');});}

async function performAction(data){const {office:action,person:id,room,seat}=data;switch(action){
 case 'cancel':ui.closeModal();break;
 case 'secret':toggleSecret(id);break;
 case 'edit-person':closePersonMenu();editPerson(id);break;
 case 'person-notes':showPersonNotes(id);break;
 case 'person-menu':{const anchor=document.querySelector(`[data-office="person-menu"][data-person="${id}"]`),box=anchor.getBoundingClientRect();openPersonMenu(id,{x:box.right-240,y:box.bottom+7},anchor);break;}
 case 'person-map':closePersonMenu();location.hash=`#/map?person=${encodeURIComponent(id)}`;break;
 case 'toggle-edit':map.editing=!map.editing;renderMapPage();break;
 case 'add-room':showRoomForm();break;
 case 'edit-room':showRoomForm(room);break;
 case 'add-seat':showSeatForm(null,room);break;
 case 'edit-seat':showSeatForm(seat);break;
 case 'resize-floor':showFloorSize();break;
 case 'add-floor':showAddFloor();break;
 case 'mode-plan':map.mode='plan';renderMapPage();break;
 case 'mode-list':map.mode='list';renderMapPage();break;
 case 'zoom-in':zoom(.8);break;
 case 'zoom-out':zoom(1.25);break;
 case 'fit':map.roomId='';map.camera=null;$('#office-room').value='';drawFloor();renderSeatList();renderDetails();break;
 case 'select-seat':selectSeat(seat);break;
 case 'find-room':map.mode='plan';map.roomId=room;map.seatId='';map.camera=null;renderMapPage();break;
 case 'find-seat':{map.mode='plan';map.seatId=seat;map.roomId=floorData().seats.find(s=>s.id===seat)?.roomId||'';map.camera=null;renderMapPage();selectSeat(seat);break;}
 case 'select-room':map.roomId=room;map.seatId='';map.camera=null;$('#office-room').value=room;drawFloor();renderSeatList();renderDetails();if(map.editing&&matchMedia('(max-width:760px)').matches)showRoomForm(room);break;
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-office]');if(!el||!activeView)return;event.preventDefault();event.stopImmediatePropagation();performAction({...el.dataset}).catch(formError);});
document.addEventListener('keydown',handleOfficeKeys);
document.addEventListener('keyup',event=>{if(event.code==='Space'&&map){map.spacePanning=false;$('#office-viewport')?.classList.remove('hand-tool');}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')hideOfficeSecrets();});

let personMenuAnchor=null;
function closePersonMenu(restoreFocus=false){$('#office-person-menu')?.remove();if(personMenuAnchor?.isConnected){personMenuAnchor.setAttribute('aria-expanded','false');if(restoreFocus)personMenuAnchor.focus({preventScroll:true});}personMenuAnchor=null;}
function openPersonMenu(id,point,anchor){
 const p=person(id);if(!p)return;
 closePersonMenu();hideOfficeSecrets();personMenuAnchor=anchor||document.activeElement;
 personMenuAnchor?.setAttribute?.('aria-expanded','true');
 const menu=document.createElement('div');menu.id='office-person-menu';menu.className='office-context-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label',`Действия: ${p.name}`);
 menu.innerHTML=`<div class="context-menu-heading">${e(p.name)}</div>${btn('person-notes',`${i('clipboard')}Заметка сотрудника`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item')}${btn('edit-person',`${i('edit')}Редактировать карточку`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item')}${locationForPerson(state.office,id)?btn('person-map',`${i('map')}Показать на карте`,`data-person="${e(id)}" role="menuitem" tabindex="-1"`,'context-menu-item'):''}`;
 document.body.append(menu);
 const box=menu.getBoundingClientRect(),bottom=matchMedia('(max-width:760px)').matches?80:10;
 menu.style.left=Math.max(10,Math.min(point.x,innerWidth-box.width-10))+'px';menu.style.top=Math.max(10,Math.min(point.y,innerHeight-box.height-bottom))+'px';
 menu.querySelector('[role=menuitem]')?.focus({preventScroll:true});
}
function employeeNote(p){return p.notes?`<section class="employee-note"><div class="between"><span>${i('clipboard')}Заметка</span>${btn('person-notes',i('edit'),`data-person="${e(p.id)}" aria-label="Изменить заметку ${e(p.name)}"`,'icon-btn')}</div><p class="employee-note-preview">${e(p.notes.length>220?p.notes.slice(0,219)+'…':p.notes)}</p>${p.notes.length>220?btn('person-notes','Читать полностью',`data-person="${e(p.id)}"`,'text-link'):''}</section>`:btn('person-notes',`${i('plus')}Добавить заметку`,`data-person="${e(p.id)}"`,'person-note-empty');}
function notesField(p){return `<div class="field office-field-full"><label for="person-notes">Описание и заметки</label><textarea id="person-notes" rows="4" maxlength="5000" placeholder="Особенности рабочего места, ПО или полезные детали…">${e(p.notes||'')}</textarea></div>`;}
function showPersonNotes(id){
 const p=person(id);if(!p)return;closePersonMenu();hideOfficeSecrets();
 const updated=p.notesUpdatedAt?new Date(p.notesUpdatedAt).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):'';
 ui.showModal('Заметка сотрудника',`<div class="note-person-header"><span class="avatar ${e(p.color)}">${e(p.initials)}</span><div><strong>${e(p.name)}</strong><p>${e(p.department)}</p></div></div><form id="employee-note-form">${notesField(p)}<div class="note-editor-meta"><span>${updated?'Обновлено '+e(updated):'Сохранится в карточке сотрудника'}</span><output id="person-note-count">${(p.notes||'').length} / 5000</output></div>${formActions('Сохранить заметку')}</form>`,true);
 $('#person-notes').addEventListener('input',event=>$('#person-note-count').textContent=`${event.target.value.length} / 5000`);
 bindForm('#employee-note-form',async()=>{const notes=$('#person-notes').value.trim();await update(s=>{const entry=s.people.find(p=>p.id===id);if(!entry)throw new Error('Сотрудник не найден.');if((entry.notes||'')!==notes){entry.notes=notes;entry.notesUpdatedAt=new Date().toISOString();}});ui.closeModal();if(activeView==='people'){refreshPeople();document.querySelector(`[data-employee-id="${id}"] [data-office="person-menu"]`)?.focus({preventScroll:true});}else if(activeView==='map')renderDetails();ui.toast('Заметка сохранена');});
}
function handleOfficeKeys(event){
 const menu=$('#office-person-menu');
 if(menu){
   const items=[...menu.querySelectorAll('[role=menuitem]')],index=items.indexOf(document.activeElement);
   if(['ArrowDown','ArrowUp','Home','End','Escape','Tab'].includes(event.key)){
     event.preventDefault();event.stopImmediatePropagation();
     if(event.key==='Escape'||event.key==='Tab'){closePersonMenu(true);return;}
     items[event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:items.length-1))%items.length]?.focus();return;
   }
 }
 if(!activeView)return;
 const employee=event.target.closest('[data-employee-id]');
 if(employee?.dataset.employeeId&&(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')){event.preventDefault();const box=employee.getBoundingClientRect();openPersonMenu(employee.dataset.employeeId,{x:box.left+20,y:box.top+35},employee);return;}
 const editable=event.target.closest('input,textarea,select,[contenteditable=true]');
 if(activeView==='map'&&map.editing&&!editable&&event.code==='Space'&&(map.canvasHovered||event.target.closest('#office-svg'))){event.preventDefault();map.spacePanning=true;$('#office-viewport')?.classList.add('hand-tool');return;}
 const el=event.target.closest('[data-office]');
 if(activeView==='map'&&map.editing&&el?.matches('.office-seat')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){
   event.preventDefault();event.stopImmediatePropagation();if(map.dragging)return;
   const id=el.dataset.seat,floorId=map.floorId,step=event.shiftKey?10:1,dx=event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0,dy=event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0;
   update(s=>{const floor=s.office.floors.find(f=>f.id===floorId),seat=floor.seats.find(s=>s.id===id);moveSeat(floor,id,seat.x+dx,seat.y+dy,{snap:1});}).then(()=>{if(activeView!=='map'||map.floorId!==floorId)return;map.seatId=id;drawFloor();renderDetails();$('#office-svg').querySelector(`[data-seat="${id}"]`)?.focus({preventScroll:true});const seat=floorData().seats.find(s=>s.id===id);mapStatus(`Сохранено · X ${seat.x} · Y ${seat.y}`);}).catch(error=>mapStatus(error.message,true));return;
 }
 if(el&&el.tagName.toLowerCase()==='g'&&['Enter',' '].includes(event.key)){event.preventDefault();performAction({...el.dataset}).catch(formError);}
}
document.addEventListener('contextmenu',event=>{const target=event.target.closest('[data-employee-id]'),id=target?.dataset.employeeId;if(!activeView||!id)return;event.preventDefault();const box=target.getBoundingClientRect();openPersonMenu(id,{x:event.clientX||box.left+20,y:event.clientY||box.top+35},target);});
document.addEventListener('pointerdown',event=>{if($('#office-person-menu')&&!event.target.closest('#office-person-menu,[data-office="person-menu"]'))closePersonMenu();},true);
window.addEventListener('scroll',()=>closePersonMenu(),{capture:true,passive:true});
window.addEventListener('resize',()=>closePersonMenu());
